"""Standalone emergency POS page for temporary offline sales."""
from __future__ import annotations
import json
import pandas as pd


def make_offline_pos(products: pd.DataFrame, shop_name: str = "Boutique Senegal") -> bytes:
    catalog=[{"id":int(r.id),"name":str(r.Produit),"price":float(r.Vente),"stock":int(r.Stock)} for _,r in products.iterrows()]
    payload=json.dumps(catalog,ensure_ascii=False).replace("</","<\\/")
    title=json.dumps(str(shop_name),ensure_ascii=False)
    html="""<!doctype html><html lang='fr'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Caisse hors connexion</title><style>body{font-family:system-ui;margin:auto;max-width:560px;padding:16px;background:#f4f7f5;color:#12372a}h1{font-size:24px}select,input,button{width:100%;box-sizing:border-box;padding:13px;margin:6px 0;border:1px solid #9aa;border-radius:10px;font-size:16px}button{background:#12372a;color:white;font-weight:700}.secondary{background:white;color:#12372a}.card{background:white;padding:14px;border-radius:14px;margin:12px 0;box-shadow:0 2px 8px #0001}table{width:100%;border-collapse:collapse}td,th{padding:7px;border-bottom:1px solid #ddd;text-align:left}.total{font-size:22px;font-weight:800;text-align:right}</style></head><body><h1 id='shop'></h1><p><b>Caisse de secours hors connexion</b></p><div class='card'><label>Produit</label><select id='product'></select><label>Quantité</label><input id='qty' type='number' min='1' value='1'><button onclick='addLine()'>Ajouter</button></div><div class='card'><table><thead><tr><th>Produit</th><th>Qté</th><th>Total</th></tr></thead><tbody id='cart'></tbody></table><p class='total' id='total'>0 FCFA</p><button onclick='saveSale()'>Enregistrer la vente hors ligne</button><button class='secondary' onclick='clearCart()'>Vider</button></div><div class='card'><p id='pending'></p><button onclick='exportSales()'>Exporter les ventes à synchroniser</button></div><script>const PRODUCTS=__PRODUCTS__;const SHOP=__SHOP__;let cart=[];document.getElementById('shop').textContent=SHOP;const sel=document.getElementById('product');PRODUCTS.forEach(p=>{let o=document.createElement('option');o.value=p.id;o.textContent=`${p.name} - ${p.price.toLocaleString('fr-FR')} FCFA`;sel.appendChild(o)});function render(){let body=document.getElementById('cart');body.innerHTML='';let total=0;cart.forEach(x=>{total+=x.quantity*x.sale_price;let tr=document.createElement('tr');tr.innerHTML=`<td>${x.name}</td><td>${x.quantity}</td><td>${(x.quantity*x.sale_price).toLocaleString('fr-FR')}</td>`;body.appendChild(tr)});document.getElementById('total').textContent=total.toLocaleString('fr-FR')+' FCFA';let saved=JSON.parse(localStorage.getItem('boutiqueOfflineSales')||'[]');document.getElementById('pending').textContent=saved.length+' vente(s) en attente de synchronisation'}function addLine(){let p=PRODUCTS.find(x=>x.id==sel.value),q=Math.max(1,parseInt(document.getElementById('qty').value||'1')),line=cart.find(x=>x.id==p.id);if(line)line.quantity+=q;else cart.push({id:p.id,name:p.name,quantity:q,sale_price:p.price});render()}function clearCart(){cart=[];render()}function saveSale(){if(!cart.length)return alert('Ajoutez un produit.');let saved=JSON.parse(localStorage.getItem('boutiqueOfflineSales')||'[]');saved.push({offline_id:crypto.randomUUID?crypto.randomUUID():Date.now().toString(),created_at:new Date().toISOString(),items:cart});localStorage.setItem('boutiqueOfflineSales',JSON.stringify(saved));cart=[];render();alert('Vente conservée sur cet appareil.')}function exportSales(){let saved=JSON.parse(localStorage.getItem('boutiqueOfflineSales')||'[]');if(!saved.length)return alert('Aucune vente en attente.');let blob=new Blob([JSON.stringify({format:'boutique-offline-sales',version:1,sales:saved},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ventes_hors_connexion.json';a.click()}render();</script></body></html>"""
    return html.replace("__PRODUCTS__",payload).replace("__SHOP__",title).encode("utf-8")
